from abc import ABC, abstractmethod


class Calculator(ABC):
    @abstractmethod
    def calculate(self, value: float) -> float:
        pass


class TypeACalculator(Calculator):
    def calculate(self, value: float) -> float:
        return value * 1.1


class TypeBCalculator(Calculator):
    def calculate(self, value: float) -> float:
        return value * 0.9


class TypeCCalculator(Calculator):
    def calculate(self, value: float) -> float:
        return value * 1.05


class CalculatorFactory:
    _calculators = {
        'A': TypeACalculator,
        'B': TypeBCalculator,
        'C': TypeCCalculator,
    }

    @classmethod
    def get_calculator(cls, item_type: str) -> Calculator:
        calculator_class = cls._calculators.get(item_type)
        if not calculator_class:
            raise ValueError(f"Unknown type: {item_type}")
        return calculator_class()


def calculate(data):
    total = 0
    for item in data:
        calculator = CalculatorFactory.get_calculator(item['type'])
        total += calculator.calculate(item['value'])
    return total

